async function connectSyncCode(nextCode) {
  syncCode = normalizeSyncCode(nextCode);
  if (!syncCode) {
    clearSyncMeta();
    restartSyncPolling();
    refreshSyncStatus();
    return;
  }
  syncKnownUpdatedAt = "";
  persistSyncMeta();
  setSyncStatus(t("sync_connecting"));
  restartSyncPolling();
  await pullPlannerStateFromRemote();
  refreshSyncStatus();
}

if (syncCodeInput) {
  syncCodeInput.value = syncCode;
  syncCodeInput.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    if (saveSyncCodeButton) saveSyncCodeButton.click();
  });
}

if (saveSyncCodeButton) {
  saveSyncCodeButton.addEventListener("click", async () => {
    const nextCode = normalizeSyncCode(syncCodeInput?.value || "");
    if (syncCodeInput) syncCodeInput.value = nextCode;
    await connectSyncCode(nextCode);
  });
}

if (clearSyncCodeButton) {
  clearSyncCodeButton.addEventListener("click", () => {
    syncCode = "";
    if (syncCodeInput) syncCodeInput.value = "";
    clearSyncMeta();
    restartSyncPolling();
    refreshSyncStatus();
  });
}

if (syncNowButton) {
  syncNowButton.addEventListener("click", async () => {
    if (!isSyncEnabled()) {
      refreshSyncStatus();
      return;
    }
    if (syncSaveTimer) {
      clearTimeout(syncSaveTimer);
      syncSaveTimer = null;
    }
    try {
      const row = await pushPlannerStateToRemote();
      syncKnownUpdatedAt = String(row?.updated_at || syncKnownUpdatedAt || "");
      persistSyncMeta();
      await pullPlannerStateFromRemote();
      refreshSyncStatus();
    } catch (error) {
      setSyncStatus(t("sync_failed"), "error");
    }
  });
}

function saveState() {
  selectedRecipesByWeek[currentWeekKey] = [...selectedRecipes];
  checkedItemsByWeek[currentWeekKey] = { ...checkedItems };
  selectedServingsByWeek[currentWeekKey] = { ...selectedServings };
  cleanupWeekState(currentWeekKey);
  persistLocalState();
  scheduleRemoteSync();
}

function renderRatingStars(target, recipeId) {
  target.innerHTML = "";
  target.classList.add("rating");
  const current = ratingsByRecipe[recipeId] || 0;
  for (let i = 1; i <= 5; i += 1) {
    const star = document.createElement("button");
    star.type = "button";
    star.className = `star ${i <= current ? "is-filled" : ""}`;
    star.textContent = "★";
    star.setAttribute("aria-label", `Rate ${i} star${i === 1 ? "" : "s"}`);
    star.addEventListener("click", (event) => {
      event.stopPropagation();
      ratingsByRecipe[recipeId] = i;
      saveState();
      renderRatingStars(target, recipeId);
      renderRecipeGrid();
    });
    target.appendChild(star);
  }
}

function getRecipeById(id) {
  return recipes.find((recipe) => recipe.id === id);
}

function getSelectionGuidance(count) {
  if (!count) return t("selection_progress_empty", WEEKLY_RECIPE_TARGET);
  if (count < WEEKLY_RECIPE_TARGET) {
    return t("selection_progress_remaining", WEEKLY_RECIPE_TARGET - count);
  }
  if (count === WEEKLY_RECIPE_TARGET) return t("selection_progress_ready");
  return t("selection_progress_extra", count, WEEKLY_RECIPE_TARGET);
}

function renderSelectedInLibrary() {
  if (!selectedList) return;
  selectedList.innerHTML = "";
  const count = selectedRecipes.length;
  const progressCard = document.createElement("section");
  progressCard.className = `selection-progress${count >= WEEKLY_RECIPE_TARGET ? " is-ready" : ""}`;

  const progressTop = document.createElement("div");
  progressTop.className = "selection-progress-top";

  const progressCopy = document.createElement("div");
  progressCopy.className = "selection-progress-copy";

  const progressCount = document.createElement("strong");
  progressCount.className = "selection-progress-count";
  progressCount.textContent = t("selection_progress", count, WEEKLY_RECIPE_TARGET);

  const progressText = document.createElement("p");
  progressText.className = "selection-progress-text";
  progressText.textContent = getSelectionGuidance(count);
  progressCopy.append(progressCount, progressText);

  const progressTarget = document.createElement("span");
  progressTarget.className = "selection-target";
  progressTarget.textContent = `~${WEEKLY_RECIPE_TARGET}`;
  progressTarget.title = t("selection_progress_empty", WEEKLY_RECIPE_TARGET);
  progressTop.append(progressCopy, progressTarget);

  const progressMeter = document.createElement("div");
  progressMeter.className = "selection-meter";
  const progressFill = document.createElement("span");
  progressFill.className = "selection-meter-fill";
  progressFill.style.width = `${Math.min(100, (count / WEEKLY_RECIPE_TARGET) * 100)}%`;
  progressMeter.appendChild(progressFill);
  const quickActions = document.createElement("div");
  quickActions.className = "selection-quick-actions";

  const duplicateButton = document.createElement("button");
  duplicateButton.type = "button";
  duplicateButton.className = "ghost";
  duplicateButton.textContent = t("duplicate_last_week");
  const { sourceWeekKey, recipeIds } = getLastWeekPlanningMeta(currentWeekKey);
  duplicateButton.disabled = !sourceWeekKey || !recipeIds.length;
  duplicateButton.addEventListener("click", duplicateLastWeekPlan);

  const autoFillButton = document.createElement("button");
  autoFillButton.type = "button";
  autoFillButton.className = "ghost";
  autoFillButton.textContent = t("auto_fill_week");
  autoFillButton.disabled = count >= WEEKLY_RECIPE_TARGET;
  autoFillButton.title = autoFillButton.disabled ? t("auto_fill_disabled") : "";
  autoFillButton.addEventListener("click", autoFillWeekPlan);

  const clearButton = document.createElement("button");
  clearButton.type = "button";
  clearButton.className = "ghost";
  clearButton.textContent = t("clear_plan");
  clearButton.disabled = !hasWeekPlanningData(currentWeekKey);
  clearButton.addEventListener("click", clearCurrentWeekPlan);

  quickActions.append(duplicateButton, autoFillButton, clearButton);
  progressCard.append(progressTop, progressMeter, quickActions);
  selectedList.appendChild(progressCard);

  const summary = document.createElement("section");
  summary.className = "selection-summary";
  const summaryLabel = document.createElement("span");
  summaryLabel.className = "selection-summary-label";
  summaryLabel.textContent = t("selection_summary_label");
  summary.appendChild(summaryLabel);

  if (count) {
    const chipList = document.createElement("div");
    chipList.className = "selection-chip-list";
    selectedRecipes.slice(0, WEEKLY_RECIPE_TARGET).forEach((recipeId) => {
      const recipe = getRecipeById(recipeId);
      if (!recipe) return;
      const chip = document.createElement("span");
      chip.className = "selection-chip";
      chip.textContent = getRecipeName(recipe);
      chipList.appendChild(chip);
    });
    if (count > WEEKLY_RECIPE_TARGET) {
      const extraChip = document.createElement("span");
      extraChip.className = "selection-chip is-overflow";
      extraChip.textContent = t("selection_summary_more", count - WEEKLY_RECIPE_TARGET);
      chipList.appendChild(extraChip);
    }
    summary.appendChild(chipList);
  } else {
    const empty = document.createElement("p");
    empty.className = "selection-summary-empty";
    empty.textContent = t("pick_summary_empty");
    summary.appendChild(empty);
  }

  selectedList.appendChild(summary);

  if (!count) return;

  selectedRecipes.forEach((recipeId) => {
    const recipe = getRecipeById(recipeId);
    if (!recipe) return;
    const row = document.createElement("div");
    row.className = "pick-item";

    const left = document.createElement("div");
    left.className = "pick-main";
    const titleRow = document.createElement("div");
    titleRow.className = "pick-title-row";
    const title = document.createElement("strong");
    title.textContent = getRecipeName(recipe);
    titleRow.appendChild(title);
    if (isFavoriteRecipe(recipeId)) {
      const favoriteBadge = document.createElement("span");
      favoriteBadge.className = "pick-favorite-badge";
      favoriteBadge.textContent = "★";
      favoriteBadge.title = t("favorite_badge");
      titleRow.appendChild(favoriteBadge);
    }
    const meta = document.createElement("span");
    meta.className = "pick-meta";
    const utensil = getUtensilLabel(recipe);
    const protein = getProteinLabel(recipe);
    meta.textContent = `${recipe.time} · ${utensil} · ${protein}`;
    left.append(titleRow, meta);

    const controls = document.createElement("div");
    controls.className = "serving-controls";
    const label = document.createElement("span");
    label.textContent = t("servings_label");
    const minus = document.createElement("button");
    minus.className = "ghost";
    minus.textContent = "-";
    minus.addEventListener("click", () => {
      const current = selectedServings[recipeId] || recipe.servings;
      if (current > 1) {
        selectedServings[recipeId] = current - 1;
        saveState();
        refreshAll();
      }
    });
    const count = document.createElement("span");
    count.className = "count";
    count.textContent = String(selectedServings[recipeId] || recipe.servings);

    const plus = document.createElement("button");
    plus.className = "ghost";
    plus.textContent = "+";
    plus.addEventListener("click", () => {
      const current = selectedServings[recipeId] || recipe.servings;
      selectedServings[recipeId] = current + 1;
      saveState();
      refreshAll();
    });
    controls.append(label, minus, count, plus);

    const removeBtn = document.createElement("button");
    removeBtn.className = "ghost pick-remove";
    removeBtn.type = "button";
    removeBtn.setAttribute("aria-label", `${t("remove")} ${getRecipeName(recipe)}`);
    removeBtn.textContent = `× ${t("remove")}`;
    removeBtn.addEventListener("click", () => {
      selectedRecipes = selectedRecipes.filter((id) => id !== recipeId);
      delete selectedServings[recipeId];
      saveState();
      refreshAll();
    });
    controls.appendChild(removeBtn);

    row.append(left, controls);
    selectedList.appendChild(row);

    if (recipeId === lastAddedRecipeId) {
      row.classList.add("pick-item-highlight");
      setTimeout(() => {
        row.classList.remove("pick-item-highlight");
      }, 900);
    }
  });
}

function getFrequencyWeekKeys() {
  const fromSelections = Object.keys(selectedRecipesByWeek)
    .filter((weekKey) => {
      const [yearPart, weekPart] = weekKey.split("-W");
      const year = parseInt(yearPart, 10);
      const week = parseInt(weekPart, 10);
      return Boolean(year && week);
    })
    .sort((a, b) => {
      const [yearA, weekA] = a.split("-W").map((value) => parseInt(value, 10));
      const [yearB, weekB] = b.split("-W").map((value) => parseInt(value, 10));
      return getDateFromISOWeek(yearA, weekA) - getDateFromISOWeek(yearB, weekB);
    });

  const comingWeekKey = getNextWeekKey();
  const [comingYear, comingWeek] = comingWeekKey.split("-W").map((value) => parseInt(value, 10));
  const comingDate = getDateFromISOWeek(comingYear, comingWeek);
  const sixWeeksBeforeComing = new Date(comingDate);
  sixWeeksBeforeComing.setDate(sixWeeksBeforeComing.getDate() - 6 * 7);

  const earliestSelected = fromSelections[0]
    ? (() => {
      const [year, week] = fromSelections[0].split("-W").map((value) => parseInt(value, 10));
      return getDateFromISOWeek(year, week);
    })()
    : null;
  const latestSelected = fromSelections[fromSelections.length - 1]
    ? (() => {
      const [year, week] = fromSelections[fromSelections.length - 1].split("-W").map((value) => parseInt(value, 10));
      return getDateFromISOWeek(year, week);
    })()
    : null;

  const rangeStart = earliestSelected && earliestSelected < sixWeeksBeforeComing
    ? earliestSelected
    : sixWeeksBeforeComing;
  const rangeEnd = latestSelected && latestSelected > comingDate
    ? latestSelected
    : comingDate;

  const weeks = [];
  const cursor = new Date(rangeStart);
  while (cursor <= rangeEnd) {
    weeks.push(getWeekKeyFromDate(cursor));
    cursor.setDate(cursor.getDate() + 7);
  }
  return Array.from(new Set(weeks));
}

function getFrequencyWindowStartKey() {
  const comingWeekKey = getNextWeekKey();
  const [year, week] = comingWeekKey.split("-W").map((value) => parseInt(value, 10));
  const date = getDateFromISOWeek(year, week);
  date.setDate(date.getDate() - 6 * 7);
  return getWeekKeyFromDate(date);
}

function focusFrequencyRecentWindow() {
  if (!frequencyTableWrap || !frequencyTable) return;
  const targetWeekKey = getFrequencyWindowStartKey();
  const targetHeader = frequencyTable.querySelector(`th[data-week-key="${targetWeekKey}"]`);
  if (!targetHeader) return;
  const recipeColWidth = 190;
  frequencyTableWrap.scrollLeft = Math.max(0, targetHeader.offsetLeft - recipeColWidth);
}

function getFrequencyRows(weekKeys) {
  const known = recipes.map((recipe) => {
    const count = weekKeys.reduce((acc, weekKey) => {
      const picks = selectedRecipesByWeek[weekKey] || [];
      return acc + (picks.includes(recipe.id) ? 1 : 0);
    }, 0);
    return {
      id: recipe.id,
      label: getRecipeName(recipe),
      count,
    };
  }).filter((row) => row.count > 0);

  const knownIds = new Set(recipes.map((recipe) => recipe.id));
  const unknownIdCounts = new Map();
  weekKeys.forEach((weekKey) => {
    const picks = selectedRecipesByWeek[weekKey] || [];
    picks.forEach((recipeId) => {
      if (!recipeId || knownIds.has(recipeId)) return;
      const count = unknownIdCounts.get(recipeId) || 0;
      unknownIdCounts.set(recipeId, count + 1);
    });
  });

  const unknown = Array.from(unknownIdCounts.entries()).map(([id, count]) => ({
    id,
    label: id,
    count,
  }));

  return [...known, ...unknown].sort((a, b) => a.label.localeCompare(b.label));
}

function renderFrequencyTable() {
  if (!frequencyTable || !frequencyTableWrap || !frequencySubtitle || !frequencyEmpty) return;
  const weekKeys = getFrequencyWeekKeys();
  const rows = getFrequencyRows(weekKeys);

  frequencySubtitle.textContent = t("frequency_subtitle", rows.length, weekKeys.length);
  frequencyTable.innerHTML = "";

  if (!weekKeys.length || !rows.length) {
    frequencyTableWrap.style.display = "none";
    frequencyEmpty.style.display = "block";
    return;
  }

  frequencyTableWrap.style.display = "block";
  frequencyEmpty.style.display = "none";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const corner = document.createElement("th");
  corner.className = "freq-recipe-head";
  corner.textContent = t("frequency_recipe");
  headRow.appendChild(corner);

  weekKeys.forEach((weekKey) => {
    const th = document.createElement("th");
    th.className = "freq-week-head";
    th.dataset.weekKey = weekKey;
    const weekPart = weekKey.split("-W")[1] || "";
    const [yearPart] = weekKey.split("-W");
    const year = parseInt(yearPart, 10);
    const week = parseInt(weekPart, 10);
    const date = getDateFromISOWeek(year, week);
    const shortDate = date.toLocaleDateString(getDateLocale(), { day: "numeric", month: "short" });
    th.innerHTML = `<span>W${weekPart}</span><small>${shortDate}</small>`;
    th.title = formatWeekLabel(weekKey);
    headRow.appendChild(th);
  });
  thead.appendChild(headRow);

  const tbody = document.createElement("tbody");
  rows.forEach(({ id, label: recipeLabel, count }) => {
    const row = document.createElement("tr");

    const labelCell = document.createElement("th");
    labelCell.className = "freq-recipe-cell";
    labelCell.innerHTML = `<span class="freq-recipe-name">${recipeLabel}</span><span class="freq-recipe-ratio">${count}/${weekKeys.length}</span>`;
    row.appendChild(labelCell);

    weekKeys.forEach((weekKey) => {
      const td = document.createElement("td");
      const isSelected = (selectedRecipesByWeek[weekKey] || []).includes(id);
      td.className = "freq-cell";
      if (isSelected) {
        const tick = document.createElement("span");
        tick.className = "freq-tick";
        tick.textContent = "✓";
        td.appendChild(tick);
      }
      row.appendChild(td);
    });

    tbody.appendChild(row);
  });

  frequencyTable.append(thead, tbody);
}

function getUtensilLabel(recipe) {
  const tags = recipe.tags || [];
  if (tags.includes("thermomix")) return t("utensil_thermomix");
  if (tags.includes("oven")) return t("utensil_oven");
  if (tags.includes("airfryer")) return t("utensil_airfryer");
  if (tags.includes("pan")) return t("utensil_pan");
  if (tags.includes("no-cook")) return t("utensil_nocook");
  return t("utensil_multi");
}

function hasProteinIngredient(items, token) {
  return items.some((item) => item.includes(token) && !item.includes("stock"));
}

function getProteinLabel(recipe) {
  const items = recipe.ingredients.map((ing) => ing.item.toLowerCase());
  if (hasProteinIngredient(items, "chicken")) return t("protein_chicken");
  if (hasProteinIngredient(items, "turkey")) return t("protein_chicken");
  if (hasProteinIngredient(items, "beef")) return t("protein_beef");
  if (hasProteinIngredient(items, "pork")) return t("protein_pork");
  if (hasProteinIngredient(items, "fish")) return t("protein_fish");
  if (hasProteinIngredient(items, "salmon")) return t("protein_fish");
  if (hasProteinIngredient(items, "prawn")) return t("protein_seafood");
  if (hasProteinIngredient(items, "lamb")) return t("protein_beef");
  if (items.some((item) => item.includes("chickpea") || item.includes("lentil") || item.includes("bean"))) {
    return t("protein_vegetarian");
  }
  return t("protein_vegetarian");
}

function getProteinKey(recipe) {
  const items = recipe.ingredients.map((ing) => ing.item.toLowerCase());
  if (hasProteinIngredient(items, "chicken")) return "chicken";
  if (hasProteinIngredient(items, "turkey")) return "chicken";
  if (hasProteinIngredient(items, "beef")) return "beef";
  if (hasProteinIngredient(items, "pork")) return "pork";
  if (hasProteinIngredient(items, "fish")) return "fish";
  if (hasProteinIngredient(items, "salmon")) return "fish";
  if (hasProteinIngredient(items, "prawn")) return "seafood";
  if (hasProteinIngredient(items, "lamb")) return "beef";
  return "vegetarian";
}

function getMealType(recipe) {
  const name = recipe.name.toLowerCase();
  const tags = recipe.tags || [];
  if (name.includes("soup") || name.includes("soupy") || name.includes("harira")) return "soup";
  if (tags.includes("salad") || name.includes("tabbouleh") || name.includes("taboule") || name.includes("salad")) return "salad";
  if (tags.includes("oven") || name.includes("gratin") || name.includes("lasagne") || name.includes("quiche") || name.includes("tian") || name.includes("moussaka") || name.includes("parmigiana")) {
    return "bake";
  }
  return "main";
}

function getMealLabel(recipe) {
  return t(`meal_${getMealType(recipe)}`);
}

function getRecipeCardTags(recipe, time) {
  const tags = recipe.tags || [];
  const mealType = getMealType(recipe);
  const cardTags = [];
  const addTag = (key, label) => {
    if (!cardTags.some((tag) => tag.key === key)) cardTags.push({ key, label });
  };

  if (time.total <= 30) addTag("quick", t("card_tag_quick"));
  if (tags.includes("vegetarian") || getProteinKey(recipe) === "vegetarian") {
    addTag("vegetarian", t("card_tag_vegetarian"));
  }
  if (tags.includes("no-cook")) addTag("no-cook", t("card_tag_no_cook"));
  if (tags.includes("batch")) addTag("family", t("card_tag_family"));
  if (mealType === "bake" || mealType === "soup") addTag("comfort", t("card_tag_comfort"));
  if (
    tags.includes("gluten-free") ||
    tags.includes("high-protein") ||
    tags.includes("vegetarian") ||
    mealType === "salad" ||
    mealType === "soup"
  ) {
    addTag("healthy", t("card_tag_healthy"));
  }

  return cardTags.slice(0, 4);
}

function getRecipeIcon(recipe) {
  const name = `${recipe.name} ${recipe.name_fr}`.toLowerCase();
  if (name.includes("lasagne") || name.includes("spaghetti")) return "🍝";
  if (name.includes("soup") || name.includes("soupe")) return "🥣";
  if (name.includes("salad") || name.includes("salade") || name.includes("taboul")) return "🥗";
  if (name.includes("curry")) return "🍛";
  if (name.includes("chili")) return "🌶️";
  if (name.includes("quiche")) return "🥧";
  if (name.includes("gratin")) return "🥔";
  if (name.includes("ratatouille")) return "🍆";
  if (name.includes("fajitas")) return "🌮";
  if (name.includes("fish") || name.includes("poisson")) return "🐟";
  if (name.includes("chicken") || name.includes("poulet")) return "🍗";
  if (name.includes("eggplant") || name.includes("aubergine")) return "🍆";
  if (name.includes("beans") || name.includes("lentil") || name.includes("lentille")) return "🫘";
  return "🍽️";
}

function computeTimeBreakdown(recipe) {
  let cook = 0;
  let prep = 0;
  const cookWords = ["cook", "bake", "roast", "simmer", "saute", "sauté", "boil", "grill", "fry", "sear", "blanch", "preheat"];
  recipe.steps.forEach((step) => {
    const match = step.match(/\((\d+)\s*min/i);
    if (!match) return;
    const minutes = parseInt(match[1], 10);
    const lower = step.toLowerCase();
    const isCook = cookWords.some((word) => lower.includes(word));
    if (isCook) cook += minutes;
    else prep += minutes;
  });
  const totalMatch = recipe.time.match(/(\d+)/);
  const total = totalMatch ? parseInt(totalMatch[1], 10) : cook + prep;
  if (cook + prep === 0) {
    return { total, cook: Math.max(0, total - 10), prep: Math.min(10, total) };
  }
  if (cook + prep !== total) {
    const ratio = total / (cook + prep);
    cook = Math.round(cook * ratio);
    prep = Math.max(0, total - cook);
  }
  return { total, cook, prep };
}

function getLastSelectedWeekKey(recipeId) {
  let lastKey = null;
  let lastDate = null;
  Object.keys(selectedRecipesByWeek).forEach((weekKey) => {
    const picks = selectedRecipesByWeek[weekKey] || [];
    if (!picks.includes(recipeId)) return;
    const [yearPart, weekPart] = weekKey.split("-W");
    const year = parseInt(yearPart, 10);
    const week = parseInt(weekPart, 10);
    if (!year || !week) return;
    const date = getDateFromISOWeek(year, week);
    if (!lastDate || date > lastDate) {
      lastDate = date;
      lastKey = weekKey;
    }
  });
  return lastKey;
}

function getWeeksBetween(weekKeyA, weekKeyB) {
  if (!weekKeyA || !weekKeyB) return null;
  const [yearA, weekA] = weekKeyA.split("-W").map((value) => parseInt(value, 10));
  const [yearB, weekB] = weekKeyB.split("-W").map((value) => parseInt(value, 10));
  if (!yearA || !weekA || !yearB || !weekB) return null;
  const dateA = getDateFromISOWeek(yearA, weekA);
  const dateB = getDateFromISOWeek(yearB, weekB);
  const diffWeeks = Math.round((dateA - dateB) / (7 * 24 * 60 * 60 * 1000));
  return diffWeeks;
}

function getLastSelectedLabel(recipeId) {
  const lastKey = getLastSelectedWeekKey(recipeId);
  if (!lastKey) return `x ${t("never_selected")}`;
  const weekKey = currentWeekKey || getCurrentWeekKey();
  const diff = getWeeksBetween(weekKey, lastKey);
  const weeks = diff === null ? 0 : Math.max(0, diff);
  return t("last_selected", weeks);
}

const MATCHER_INGREDIENT_ALIASES = {
  "round zucchini": "zucchini",
  "eggplants": "eggplant",
  "garlic clove": "garlic cloves",
  "brown onion": "onion",
  "red onion": "onion",
  "white onion": "onion",
  "yellow onion": "onion",
  "fresh spinach": "spinach",
  "baby spinach": "spinach",
  "cherry tomatoes": "tomatoes",
  "kale": "spinach",
  "fresh thyme": "thyme",
  "dried thyme": "thyme",
  "dried oregano": "oregano",
  "dried basil": "basil",
  "fresh coriander": "coriander",
  "beef mince": "ground beef",
  "turkey mince": "turkey",
  "egg": "eggs",
};

function normalizeMatcherIngredientKey(item) {
  const key = canonicalIngredientItem(item).toLowerCase().replace(/\s+/g, " ").trim();
  if (!key) return "";
  if (MATCHER_INGREDIENT_ALIASES[key]) return MATCHER_INGREDIENT_ALIASES[key];
  if (key === "capsicums") return "capsicum";
  if (/^(red|green|yellow|orange)\s+capsicum$/.test(key)) return "capsicum";
  if (
    key === "cream" ||
    key === "creme fraiche" ||
    key === "thickened cream" ||
    key === "plant-based cream" ||
    key === "creamy plant base"
  ) {
    return "cream";
  }
  return key;
}

function normalizePantryQuantity(qty) {
  const parsed = Number(qty);
  if (!Number.isFinite(parsed)) return 1;
  return Math.max(1, Math.round(parsed));
}

function getPantryIngredientCatalog() {
  const map = new Map();
  recipes.forEach((recipe) => {
    recipe.ingredients.forEach((ingredient) => {
      const key = normalizeMatcherIngredientKey(ingredient.item);
      if (!key) return;
      if (!map.has(key)) {
        map.set(key, {
          key,
          item: key,
          units: new Set(),
        });
      }
      map.get(key).units.add((ingredient.unit || "").toLowerCase());
    });
  });

  return Array.from(map.values())
    .map((entry) => ({
      ...entry,
      units: Array.from(entry.units).filter(Boolean).sort(),
    }))
    .sort((a, b) => translateIngredientItem(a.item).localeCompare(translateIngredientItem(b.item)));
}

function savePantryInventory() {
  persistLocalState();
  scheduleRemoteSync();
}

function sanitizePantryInventory() {
  const catalogKeys = new Set(getPantryIngredientCatalog().map((entry) => entry.key));
  const clean = {};
  Object.keys(pantryInventory || {}).forEach((key) => {
    const normalizedKey = normalizeMatcherIngredientKey(key);
    if (!catalogKeys.has(normalizedKey)) return;
    const qty = normalizePantryQuantity(pantryInventory[key]?.qty);
    const unit = String(pantryInventory[key]?.unit || "any").toLowerCase() || "any";
    const existing = clean[normalizedKey];
    if (!existing) {
      clean[normalizedKey] = {
        qty,
        unit,
      };
      return;
    }
    const mergedQty = Math.max(existing.qty, qty);
    const mergedUnit = existing.unit === unit ? unit : "any";
    clean[normalizedKey] = {
      qty: mergedQty,
      unit: mergedUnit,
    };
  });
  pantryInventory = clean;
  savePantryInventory();
}

function formatMatchIngredientLabel(ingredient) {
  const item = translateIngredientItem(normalizeMatcherIngredientKey(ingredient.item));
  const qty = formatQuantityExact(ingredient.qty);
  const unit = (ingredient.unit || "").trim();
  const qtyPart = unit && unit.toLowerCase() !== "pcs" ? `${qty} ${unit}` : qty;
  return `${item} (${qtyPart})`;
}

function getPantryRecipeMatches() {
  const selections = pantryInventory || {};
  return recipes
    .map((recipe) => {
      const found = new Map();
      recipe.ingredients.forEach((ingredient) => {
        const key = normalizeMatcherIngredientKey(ingredient.item);
        const selection = selections[key];
        if (!selection) return;
        const selectionQty = Number(selection.qty);
        if (!Number.isFinite(selectionQty) || selectionQty <= 0) return;
        const selectedUnit = String(selection.unit || "any").toLowerCase();
        const ingredientUnit = String(ingredient.unit || "").toLowerCase();
        if (selectedUnit !== "any" && selectedUnit !== ingredientUnit) return;
        if (selectedUnit !== "any" && selectionQty < ingredient.qty) return;
        if (!found.has(key)) found.set(key, ingredient);
      });

      return {
        recipe,
        matches: Array.from(found.values()),
      };
    })
    .filter((entry) => entry.matches.length > 0)
    .sort((a, b) => {
      if (b.matches.length !== a.matches.length) return b.matches.length - a.matches.length;
      return getRecipeName(a.recipe).localeCompare(getRecipeName(b.recipe));
    });
}

function renderPantrySearchResults() {
  if (!pantrySearchResults) return;
  pantrySearchResults.innerHTML = "";
  const catalog = getPantryIngredientCatalog();
  const query = (pantryIngredientSearch?.value || "").toLowerCase().trim();
  if (!query) {
    pantrySearchResults.innerHTML = `<p class="pantry-hint">${t("pantry_search_prompt")}</p>`;
    return;
  }

  const filtered = catalog
    .filter((entry) => {
      const item = entry.item.toLowerCase();
      const translated = translateIngredientItem(entry.item).toLowerCase();
      return item.includes(query) || translated.includes(query);
    })
    .slice(0, 20);

  if (!filtered.length) {
    pantrySearchResults.innerHTML = `<p class="pantry-hint">${t("pantry_search_empty")}</p>`;
    return;
  }

  filtered.forEach((entry) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pantry-option";
    button.textContent = translateIngredientItem(entry.item);
    button.addEventListener("click", () => {
      if (!pantryInventory[entry.key]) {
        pantryInventory[entry.key] = { qty: 1, unit: "any" };
        savePantryInventory();
      }
      renderPantryPicker();
      renderPantryRecipeMatches();
    });
    pantrySearchResults.appendChild(button);
  });
}

function renderPantryPicker() {
  if (!pantrySelected) return;
  pantrySelected.innerHTML = "";

  const title = document.createElement("strong");
  title.textContent = t("pantry_selected_title");
  pantrySelected.appendChild(title);

  const keys = Object.keys(pantryInventory || {}).sort((a, b) =>
    translateIngredientItem(a).localeCompare(translateIngredientItem(b))
  );
  if (!keys.length) {
    const hint = document.createElement("p");
    hint.className = "pantry-hint";
    hint.textContent = t("pantry_selected_empty");
    pantrySelected.appendChild(hint);
    return;
  }

  const catalogByKey = new Map(getPantryIngredientCatalog().map((entry) => [entry.key, entry]));
  keys.forEach((key) => {
    const row = document.createElement("div");
    row.className = "pantry-row";

    const name = document.createElement("div");
    name.className = "pantry-item-name";
    name.textContent = translateIngredientItem(key);

    const qtyLabel = document.createElement("label");
    qtyLabel.className = "pantry-control";
    qtyLabel.classList.add("pantry-qty");
    qtyLabel.innerHTML = `<span>${t("pantry_quantity")}</span>`;
    const qtyInput = document.createElement("input");
    qtyInput.type = "number";
    qtyInput.min = "1";
    qtyInput.step = "1";
    qtyInput.value = formatQuantityExact(pantryInventory[key].qty);
    qtyInput.addEventListener("change", () => {
      const normalizedQty = normalizePantryQuantity(qtyInput.value);
      pantryInventory[key].qty = normalizedQty;
      qtyInput.value = formatQuantityExact(normalizedQty);
      savePantryInventory();
      renderPantryRecipeMatches();
    });
    qtyLabel.appendChild(qtyInput);

    const unitLabel = document.createElement("label");
    unitLabel.className = "pantry-control";
    unitLabel.classList.add("pantry-unit");
    unitLabel.innerHTML = `<span>${t("pantry_unit")}</span>`;
    const unitSelect = document.createElement("select");
    const defaultOpt = document.createElement("option");
    defaultOpt.value = "any";
    defaultOpt.textContent = t("pantry_unit_any");
    unitSelect.appendChild(defaultOpt);
    (catalogByKey.get(key)?.units || []).forEach((unit) => {
      const option = document.createElement("option");
      option.value = unit;
      option.textContent = unit;
      unitSelect.appendChild(option);
    });
    unitSelect.value = pantryInventory[key].unit || "any";
    unitSelect.addEventListener("change", () => {
      pantryInventory[key].unit = unitSelect.value || "any";
      savePantryInventory();
      renderPantryRecipeMatches();
    });
    unitLabel.appendChild(unitSelect);

    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "ghost";
    remove.classList.add("pantry-remove");
    remove.textContent = t("remove");
    remove.addEventListener("click", () => {
      delete pantryInventory[key];
      savePantryInventory();
      renderPantryPicker();
      renderPantryRecipeMatches();
    });

    row.append(name, qtyLabel, unitLabel, remove);
    pantrySelected.appendChild(row);
  });
}

function renderPantryRecipeMatches() {
  if (!pantryMatchList) return;
  pantryMatchList.innerHTML = "";
  const selectedCount = Object.keys(pantryInventory || {}).length;
  if (!selectedCount) {
    pantryMatchList.innerHTML = `<p class="pantry-hint">${t("pantry_matches_empty")}</p>`;
    return;
  }

  const matches = getPantryRecipeMatches();
  if (!matches.length) {
    pantryMatchList.innerHTML = `<p class="pantry-hint">${t("pantry_matches_none")}</p>`;
    return;
  }

  matches.forEach(({ recipe, matches: matchedIngredients }) => {
    const isSelected = selectedRecipes.includes(recipe.id);
    const card = document.createElement("div");
    card.className = "pantry-match-card";

    const head = document.createElement("div");
    head.className = "pantry-match-head";
    const title = document.createElement("h3");
    title.textContent = getRecipeName(recipe);
    const count = document.createElement("span");
    count.className = "match-count";
    count.textContent = t("pantry_match_count", matchedIngredients.length);
    head.append(title, count);

    const matchesLabel = document.createElement("p");
    matchesLabel.className = "pantry-match-label";
    matchesLabel.textContent = `${t("pantry_matched_items")}: ${matchedIngredients.map(formatMatchIngredientLabel).join(", ")}`;

    const action = document.createElement("button");
    action.type = "button";
    action.className = "ghost";
    action.textContent = isSelected ? t("remove_from_picks") : t("add_to_picks");
    action.addEventListener("click", () => {
      if (selectedRecipes.includes(recipe.id)) {
        selectedRecipes = selectedRecipes.filter((id) => id !== recipe.id);
        delete selectedServings[recipe.id];
      } else {
        selectedRecipes = [...selectedRecipes, recipe.id];
        if (!selectedServings[recipe.id]) selectedServings[recipe.id] = DEFAULT_SERVINGS;
      }
      saveState();
      refreshAll();
    });

    card.addEventListener("click", (event) => {
      if (event.target === action) return;
      renderRecipeDetails(recipe);
    });

    card.append(head, matchesLabel, action);
    pantryMatchList.appendChild(card);
  });
}

function renderPantryPickerSection() {
  sanitizePantryInventory();
  renderPantrySearchResults();
  renderPantryPicker();
  renderPantryRecipeMatches();
}

function renderRecentWeeks() {
  recentWeeks.innerHTML = "";
  const weeks = Object.keys(selectedRecipesByWeek)
    .filter((weekKey) => getWeekRecipeIds(weekKey).length)
    .sort()
    .reverse();
  if (!weeks.length) return;

  const title = document.createElement("strong");
  title.textContent = t("recent_weeks");
  recentWeeks.appendChild(title);

  weeks.slice(0, 4).forEach((weekKey) => {
    const row = document.createElement("div");
    row.textContent = formatWeekLabel(weekKey);

    const button = document.createElement("button");
    button.className = "ghost";
    button.textContent = t("view");
    button.addEventListener("click", () => {
      if (topWeekPicker) topWeekPicker.value = weekKey;
      setWeekFromTopPicker();
    });

    row.appendChild(button);
    recentWeeks.appendChild(row);
  });
}

function renderRecipeGrid() {
  recipeGrid.innerHTML = "";
  const query = (recipeSearch?.value || "").toLowerCase().trim();
  const utensilFilter = filterUtensil?.value || "all";
  const proteinFilter = filterProtein?.value || "all";
  const mealFilter = filterMeal?.value || "all";

  recipes
    .filter((recipe) => {
      const matchesQuery =
        !query ||
        getRecipeName(recipe).toLowerCase().includes(query) ||
        recipe.ingredients.some((ing) => ing.item.toLowerCase().includes(query));
      const matchesUtensil =
        utensilFilter === "all" ||
        (utensilFilter === "multi" ? getUtensilLabel(recipe) === t("utensil_multi") : (recipe.tags || []).includes(utensilFilter));
      const matchesProtein = proteinFilter === "all" || getProteinKey(recipe) === proteinFilter;
      const matchesMeal = mealFilter === "all" || getMealType(recipe) === mealFilter;
      return matchesQuery && matchesUtensil && matchesProtein && matchesMeal;
    })
    .sort((a, b) => {
      const selectedA = selectedRecipes.includes(a.id);
      const selectedB = selectedRecipes.includes(b.id);
      if (selectedA !== selectedB) return selectedA ? -1 : 1;
      const favoriteA = isFavoriteRecipe(a.id);
      const favoriteB = isFavoriteRecipe(b.id);
      if (favoriteA !== favoriteB) return favoriteA ? -1 : 1;
      const previousA = isRecipePreviouslySelected(a.id);
      const previousB = isRecipePreviouslySelected(b.id);
      if (previousA !== previousB) return previousA ? -1 : 1;
      const ratingA = ratingsByRecipe[a.id] || 0;
      const ratingB = ratingsByRecipe[b.id] || 0;
      if (ratingA !== ratingB) return ratingB - ratingA;
      return getRecipeName(a).localeCompare(getRecipeName(b));
    })
    .forEach((recipe) => {
    const isSelected = selectedRecipes.includes(recipe.id);
    const isFavorite = isFavoriteRecipe(recipe.id);
    const historyLabel = getHistoricalSelectionLabel(recipe.id);
    const card = document.createElement("div");
    card.className = "recipe-card";
    if (isSelected) card.classList.add("is-selected");
    if (isFavorite) card.classList.add("is-favorite");
    if (historyLabel) card.classList.add("is-previously-selected");

    const thumb = document.createElement("div");
    thumb.className = "recipe-thumb";
    const thumbControls = document.createElement("div");
    thumbControls.className = "recipe-thumb-controls";
    const favoriteButton = document.createElement("button");
    favoriteButton.type = "button";
    favoriteButton.className = "recipe-favorite-toggle";
    if (isFavorite) favoriteButton.classList.add("is-active");
    favoriteButton.textContent = "★";
    favoriteButton.title = isFavorite ? t("favorite_remove") : t("favorite_add");
    favoriteButton.setAttribute("aria-label", isFavorite ? t("favorite_remove") : t("favorite_add"));
    favoriteButton.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleFavoriteRecipe(recipe.id);
      refreshAll();
    });
    thumbControls.appendChild(favoriteButton);
    const imageSrc = getRecipeImage(recipe);
    const fallbackSrc = buildRecipeFallbackImage(recipe);
    const img = document.createElement("img");
    const isBookPageImageSrc = isRecipeBookPageImage(imageSrc);
    img.className = "recipe-thumb-image";
    img.src = imageSrc || fallbackSrc;
    img.alt = getRecipeName(recipe);
    // Safari can fail to fetch/decode lazy images inside scrollable containers.
    img.loading = "eager";
    img.decoding = "async";
    img.draggable = false;
    if (!imageSrc) {
      thumb.classList.add("is-fallback");
      img.dataset.synthetic = "true";
      img.classList.add("fit-fallback-art");
    }
    if (isBookPageImageSrc) {
      thumb.classList.add("is-book-page");
      thumb.style.setProperty("--recipe-thumb-backdrop", `url("${escapeCssUrl(imageSrc)}")`);
      img.classList.add("fit-book-page");
    }
    const clearBookPagePresentation = () => {
      thumb.classList.remove("is-book-page");
      thumb.style.removeProperty("--recipe-thumb-backdrop");
      img.classList.remove("fit-book-page");
    };
    const swapToFallbackArt = () => {
      thumb.classList.add("is-fallback");
      img.dataset.synthetic = "true";
      clearBookPagePresentation();
      img.classList.add("fit-fallback-art");
      img.src = fallbackSrc;
    };
    img.addEventListener("error", () => {
      if (img.dataset.synthetic === "true") {
        thumb.classList.add("is-fallback");
        thumb.innerHTML = "";
        const fallback = document.createElement("span");
        fallback.textContent = getRecipeIcon(recipe);
        thumb.appendChild(fallback);
        return;
      }
      swapToFallbackArt();
    });
    thumb.appendChild(thumbControls);
    thumb.appendChild(img);
    if (isSelected) {
      const selectedBadge = document.createElement("span");
      selectedBadge.className = "selected-badge";
      selectedBadge.textContent = `✓ ${t("selected_badge")}`;
      thumb.appendChild(selectedBadge);
    }

    const info = document.createElement("div");
    info.className = "recipe-info";
    const title = document.createElement("h3");
    title.className = "recipe-title";
    title.textContent = getRecipeName(recipe);

    const utensil = getUtensilLabel(recipe);
    const protein = getProteinLabel(recipe);
    const meal = getMealLabel(recipe);
    const time = computeTimeBreakdown(recipe);
    const metaGrid = document.createElement("div");
    metaGrid.className = "recipe-card-meta";
    [
      [t("card_meta_time"), `${time.total} min`],
      [t("card_meta_servings"), String(recipe.servings)],
      [t("card_meta_protein"), protein],
    ].forEach(([label, value]) => {
      const item = document.createElement("span");
      item.className = "recipe-meta-chip";
      const metaLabel = document.createElement("small");
      metaLabel.textContent = label;
      const metaValue = document.createElement("strong");
      metaValue.textContent = value;
      item.append(metaLabel, metaValue);
      metaGrid.appendChild(item);
    });

    const contextLine = document.createElement("div");
    contextLine.className = "recipe-context";
    if (historyLabel) {
      const historyPill = document.createElement("span");
      historyPill.className = "recipe-history-pill";
      historyPill.textContent = historyLabel;
      contextLine.appendChild(historyPill);
    }
    if (isFavorite) {
      const favoritePill = document.createElement("span");
      favoritePill.className = "recipe-history-pill is-favorite";
      favoritePill.textContent = t("favorite_badge");
      contextLine.appendChild(favoritePill);
    }

    const line = document.createElement("div");
    line.className = "recipe-line";
    const parts = [utensil, meal];
    parts.forEach((part) => {
      const pill = document.createElement("span");
      pill.className = "recipe-pill";
      pill.textContent = part;
      line.appendChild(pill);
    });
    const cardTags = getRecipeCardTags(recipe, time);
    const tagLine = document.createElement("div");
    tagLine.className = "recipe-card-tags";
    cardTags.forEach((tag) => {
      const tagPill = document.createElement("span");
      tagPill.className = `recipe-card-tag is-${tag.key}`;
      tagPill.textContent = tag.label;
      tagLine.appendChild(tagPill);
    });

    info.append(title, metaGrid, line);
    if (contextLine.childElementCount) info.appendChild(contextLine);
    if (tagLine.childElementCount) info.appendChild(tagLine);

    const actionWrap = document.createElement("div");
    actionWrap.className = "recipe-card-actions";

    const actionBtn = document.createElement("button");
    actionBtn.className = "ghost";
    actionBtn.textContent = isSelected
      ? t("remove_from_picks")
      : t("add_to_picks");
    actionBtn.addEventListener("click", () => {
      if (selectedRecipes.includes(recipe.id)) {
        selectedRecipes = selectedRecipes.filter((id) => id !== recipe.id);
        delete selectedServings[recipe.id];
      } else {
        selectedRecipes = [...selectedRecipes, recipe.id];
        if (!selectedServings[recipe.id]) selectedServings[recipe.id] = DEFAULT_SERVINGS;
      }
      saveState();
      refreshAll();
    });
    actionWrap.appendChild(actionBtn);

    card.addEventListener("click", (event) => {
      if (event.target === actionBtn || event.target.closest?.(".recipe-favorite-toggle")) return;
      renderRecipeDetails(recipe);
    });

    card.append(thumb, info, actionWrap);
    recipeGrid.appendChild(card);
  });
}

function renderRecipeDetails(recipe) {
  if (!recipeDetails && !recipeModalBody) return;
  lastOpenedRecipeId = recipe.id;
  recipeDetailsOpen = true;
  persistUiState();
  const servings = recipe.servings;
  const noteValue = recipeNotesById[recipe.id] || "";
  const ingredients = recipe.ingredients.length
    ? recipe.ingredients
        .map((ingredient) => {
          const displayQty = formatQuantity(ingredient.qty, ingredient.unit);
          const displayItem = translateIngredientItem(ingredient.item);
          return `<li>${displayItem} — ${displayQty} ${ingredient.unit}</li>`;
        })
        .join("")
    : `<li>${t("ingredients_empty")}</li>`;
  const stepsForRecipe = getRecipeSteps(recipe);
  const methodSteps = stepsForRecipe.length
    ? stepsForRecipe
        .map((step, index) => `<li><span>${index + 1}</span><p>${formatStepWithQuantities(step, recipe, servings)}</p></li>`)
        .join("")
    : `<li class="is-empty"><p>${t("cook_steps_empty")}</p></li>`;
  const nutrition = calculateRecipeNutrition(recipe);
  const nutritionNote = nutrition.missing
    ? t("nutrition_note_missing")
    : t("nutrition_note");
  const favoriteLabel = isFavoriteRecipe(recipe.id) ? t("favorite_remove") : t("favorite_add");
  const nutritionHtml = `
    <div class="nutrition-panel">
      <h5>${t("nutrition_title")}</h5>
      <div class="nutrition-grid">
        <div>
          <span>${t("nutrition_calories")}</span>
          <strong>${Math.round(nutrition.perServe.kcal)} kcal</strong>
        </div>
        <div>
          <span>${t("nutrition_protein")}</span>
          <strong>${nutrition.perServe.protein.toFixed(1)} g</strong>
        </div>
        <div>
          <span>${t("nutrition_carbs")}</span>
          <strong>${nutrition.perServe.carbs.toFixed(1)} g</strong>
        </div>
        <div>
          <span>${t("nutrition_fat")}</span>
          <strong>${nutrition.perServe.fat.toFixed(1)} g</strong>
        </div>
        <div>
          <span>${t("nutrition_fiber")}</span>
          <strong>${nutrition.perServe.fiber.toFixed(1)} g</strong>
        </div>
      </div>
      <p class="nutrition-note">${nutritionNote}</p>
    </div>
  `;

  const html = `
    <h4 id="recipe-modal-title"><span class="recipe-icon">${getRecipeIcon(recipe)}</span>${getRecipeName(recipe)}</h4>
    <div class="detail-meta">${recipe.time} · ${servings} ${t("servings_label")}</div>
    <div class="rating" data-rating-for="${recipe.id}"></div>
    <button class="ghost detail-favorite-toggle" data-favorite-toggle="${recipe.id}">${favoriteLabel}</button>
    <div class="recipe-detail-tabs" role="tablist">
      <button class="recipe-detail-tab is-active" type="button" role="tab" aria-selected="true" data-recipe-panel-target="ingredients-${recipe.id}">${t("cook_section_ingredients")}</button>
      <button class="recipe-detail-tab" type="button" role="tab" aria-selected="false" data-recipe-panel-target="method-${recipe.id}">${t("cook_section_steps")}</button>
    </div>
    <section class="recipe-detail-panel is-active" id="ingredients-${recipe.id}" data-recipe-panel="ingredients-${recipe.id}" role="tabpanel">
      <div class="recipe-section-head">
        <h5>${t("cook_section_ingredients")}</h5>
        <span>${t("cook_section_ingredients_count", recipe.ingredients.length)}</span>
      </div>
      <ul class="recipe-ingredient-list">${ingredients}</ul>
      ${nutritionHtml}
    </section>
    <section class="recipe-detail-panel" id="method-${recipe.id}" data-recipe-panel="method-${recipe.id}" role="tabpanel" hidden>
      <div class="recipe-section-head">
        <h5>${t("cook_section_steps")}</h5>
        <span>${t("cook_section_steps_count", 0, stepsForRecipe.length)}</span>
      </div>
      <ol class="recipe-method-list">${methodSteps}</ol>
    </section>
    <div class="note-section">
      <label class="note-label" for="note-${recipe.id}">${t("recipe_note")}</label>
      <textarea id="note-${recipe.id}" class="note-input" rows="3" placeholder="${t("recipe_note_placeholder")}">${noteValue}</textarea>
      <div class="note-actions">
        <button class="ghost" data-note-save="${recipe.id}">${t("note_save")}</button>
        <button class="ghost" data-note-clear="${recipe.id}">${t("note_clear")}</button>
      </div>
    </div>
    ${recipe.source_url ? `<a class="ghost link-btn" href="${recipe.source_url}" target="_blank" rel="noopener">Open recipe link</a>` : ""}
  `;

  if (recipeModalBody && recipeModal) {
    recipeModalBody.innerHTML = html;
    const ratingTarget = recipeModalBody.querySelector(`[data-rating-for="${recipe.id}"]`);
    if (ratingTarget) renderRatingStars(ratingTarget, recipe.id);
    const favoriteBtn = recipeModalBody.querySelector(`[data-favorite-toggle="${recipe.id}"]`);
    const noteInput = recipeModalBody.querySelector(`#note-${recipe.id}`);
    const saveBtn = recipeModalBody.querySelector(`[data-note-save="${recipe.id}"]`);
    const clearBtn = recipeModalBody.querySelector(`[data-note-clear="${recipe.id}"]`);
    const detailTabs = Array.from(recipeModalBody.querySelectorAll("[data-recipe-panel-target]"));
    const detailPanels = Array.from(recipeModalBody.querySelectorAll("[data-recipe-panel]"));
    detailTabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        const target = tab.dataset.recipePanelTarget;
        detailTabs.forEach((candidate) => {
          const isActive = candidate === tab;
          candidate.classList.toggle("is-active", isActive);
          candidate.setAttribute("aria-selected", isActive ? "true" : "false");
        });
        detailPanels.forEach((panel) => {
          const isActive = panel.dataset.recipePanel === target;
          panel.classList.toggle("is-active", isActive);
          panel.hidden = !isActive;
        });
      });
    });
    if (favoriteBtn) {
      favoriteBtn.addEventListener("click", () => {
        toggleFavoriteRecipe(recipe.id);
        renderRecipeDetails(recipe);
        renderSelectedInLibrary();
        renderRecipeGrid();
      });
    }
    if (saveBtn && noteInput) {
      saveBtn.addEventListener("click", () => {
        recipeNotesById[recipe.id] = noteInput.value.trim();
        safeSetItem("pantryRecipeNotes", JSON.stringify(recipeNotesById));
        saveState();
      });
    }
    if (clearBtn && noteInput) {
      clearBtn.addEventListener("click", () => {
        noteInput.value = "";
        delete recipeNotesById[recipe.id];
        safeSetItem("pantryRecipeNotes", JSON.stringify(recipeNotesById));
        saveState();
      });
    }
    recipeModal.classList.add("is-open");
    recipeModal.setAttribute("aria-hidden", "false");
    if (recipeDetails) recipeDetails.innerHTML = "";
  } else if (recipeDetails) {
    recipeDetails.innerHTML = html;
  }
}

function normalizeShoppingItem(item) {
  const name = canonicalIngredientItem(item).toLowerCase().trim();
  if (name === "water" || name === "hot water") return null;
  if (name === "brown onion" || name === "white onion" || name === "yellow onion") return "onion";
  if (name === "creme fraiche") return "cream";
  return name;
}

function aggregateShoppingList() {
  const counts = {};
  selectedRecipes.forEach((recipeId) => {
    const recipe = getRecipeById(recipeId);
    if (!recipe) return;
    const servings = selectedServings[recipeId] || recipe.servings;
    recipe.ingredients.forEach((ingredient) => {
      const normalized = normalizeShoppingItem(ingredient.item);
      if (!normalized) return;
      const key = `${normalized}|${ingredient.unit}`;
      const scaledQty = (ingredient.qty / recipe.servings) * servings;
      if (!counts[key]) {
        counts[key] = { ...ingredient, item: normalized, qty: scaledQty };
      } else {
        counts[key].qty += scaledQty;
      }
    });
  });
  return Object.values(counts).sort((a, b) => a.item.localeCompare(b.item));
}

function consolidateShoppingUnits(list) {
  const grouped = new Map();
  list.forEach((ingredient) => {
    const key = ingredient.item;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(ingredient);
  });

  const result = [];
  grouped.forEach((entries, item) => {
    if (entries.length === 1) {
      result.push(entries[0]);
      return;
    }
    const parts = entries.map((entry) => {
      const qty = formatQuantity(entry.qty, entry.unit);
      return `${qty} ${entry.unit}`.trim();
    });
    result.push({
      item,
      unit: "mixed",
      qty: 0,
      compositeText: parts.join(" + "),
    });
  });

  return result;
}

function getRetailerName() {
  return preferredRetailer === "colruyt" ? "Colruyt" : "Woolworths";
}

function getRetailerSearchUrl(item) {
  if (preferredRetailer === "colruyt") {
    const translatedItem = translateIngredientItem(item);
    return `https://www.colruyt.be/fr/produits?method=suggestion&o=product%20overview&page=1&searchTerm=${encodeURIComponent(translatedItem)}&suggestion=products&type=product`;
  }
  return `https://www.woolworths.com.au/shop/search/products?searchTerm=${encodeURIComponent(item)}`;
}

function toggleHideCheckedShoppingItems() {
  hideCheckedShoppingItems = !hideCheckedShoppingItems;
  safeSetItem("pantryHideCheckedShoppingItems", hideCheckedShoppingItems ? "true" : "false");
  renderShoppingList();
}

function renderShoppingMobileBar({ hasItems, nextItem, checkedCount }) {
  if (!shoppingMobileBar) return;
  shoppingMobileBar.innerHTML = "";
  shoppingMobileBar.hidden = !hasItems;
  if (!hasItems) return;

  const retailerName = getRetailerName();
  const nextLink = document.createElement("a");
  nextLink.className = "primary link-btn shopping-next-link";
  nextLink.textContent = nextItem
    ? t("shopping_next_link", nextItem.displayItem, retailerName)
    : t("shopping_done");
  if (nextItem) {
    nextLink.href = getRetailerSearchUrl(nextItem.item);
    nextLink.target = "_blank";
    nextLink.rel = "noopener noreferrer";
    nextLink.setAttribute("aria-label", t("shopping_next_link", nextItem.displayItem, retailerName));
  } else {
    nextLink.classList.add("is-disabled");
    nextLink.removeAttribute("href");
    nextLink.setAttribute("aria-disabled", "true");
  }

  const toggleButton = document.createElement("button");
  toggleButton.type = "button";
  toggleButton.className = "ghost";
  toggleButton.textContent = hideCheckedShoppingItems
    ? t("shopping_show_checked", checkedCount)
    : t("shopping_hide_checked", checkedCount);
  toggleButton.addEventListener("click", () => {
    toggleHideCheckedShoppingItems();
  });

  shoppingMobileBar.append(nextLink, toggleButton);
}

function translateShoppingCategory(category) {
  const map = {
    "Produce": "shopping_category_produce",
    "Meat & Seafood": "shopping_category_meat",
    "Dairy": "shopping_category_dairy",
    "Grains & Pasta": "shopping_category_grains",
    "Canned & Jarred": "shopping_category_canned",
    "Frozen": "shopping_category_frozen",
    "Pantry": "shopping_category_pantry",
  };
  return t(map[category] || category);
}

function renderShoppingList() {
  shoppingList.innerHTML = "";
  if (shoppingTools) shoppingTools.hidden = false;
  if (shoppingMobileBar) {
    shoppingMobileBar.innerHTML = "";
    shoppingMobileBar.hidden = true;
  }
  const items = aggregateShoppingList();
  if (shoppingStats) shoppingStats.innerHTML = "";
  if (shoppingNextLink) {
    shoppingNextLink.removeAttribute("href");
    shoppingNextLink.classList.add("is-disabled");
    shoppingNextLink.textContent = getRetailerName();
  }
  if (shoppingToggleChecked) {
    shoppingToggleChecked.textContent = hideCheckedShoppingItems ? t("shopping_show_checked", 0) : t("shopping_hide_checked", 0);
  }
  if (!items.length) {
    if (shoppingTools) shoppingTools.hidden = true;
    shoppingList.innerHTML = `<p>${t("shopping_empty")}</p>`;
    return;
  }

  const grouped = groupShoppingItems(items).map(([category, list]) => {
    const entries = consolidateShoppingUnits(list)
      .map((ingredient) => {
        const key = ingredient.unit === "mixed" ? `${ingredient.item}|mixed` : `${ingredient.item}|${ingredient.unit}`;
        return {
          ...ingredient,
          key,
          checked: Boolean(checkedItems[key]),
          displayItem: translateIngredientItem(ingredient.item),
          displayQty: ingredient.compositeText || `${formatQuantity(ingredient.qty, ingredient.unit)} ${ingredient.unit}`.trim(),
        };
      })
      .sort((a, b) => {
        if (a.checked !== b.checked) return a.checked ? 1 : -1;
        return a.item.localeCompare(b.item);
      });

    return {
      category,
      items: entries,
      totalCount: entries.length,
      remainingCount: entries.filter((entry) => !entry.checked).length,
    };
  });

  const flattened = grouped.flatMap((group) => group.items);
  const checkedCount = flattened.filter((item) => item.checked).length;
  const remainingCount = flattened.length - checkedCount;
  const nextItem = flattened.find((item) => !item.checked) || null;
  const visibleGroups = grouped
    .map((group) => ({
      ...group,
      items: hideCheckedShoppingItems ? group.items.filter((item) => !item.checked) : group.items,
    }))
    .filter((group) => group.items.length);

  if (shoppingStats) {
    const stats = [
      { value: selectedRecipes.length, label: t("shopping_stat_recipes") },
      { value: remainingCount, label: t("shopping_stat_remaining") },
      { value: checkedCount, label: t("shopping_stat_checked") },
      { value: grouped.length, label: t("shopping_stat_sections") },
    ];
    stats.forEach(({ value, label }) => {
      const stat = document.createElement("div");
      stat.className = "shopping-stat";
      const strong = document.createElement("strong");
      strong.textContent = String(value);
      const span = document.createElement("span");
      span.textContent = label;
      stat.append(strong, span);
      shoppingStats.appendChild(stat);
    });
  }

  if (shoppingToggleChecked) {
    shoppingToggleChecked.textContent = hideCheckedShoppingItems
      ? t("shopping_show_checked", checkedCount)
      : t("shopping_hide_checked", checkedCount);
  }

  if (shoppingNextLink) {
    const retailerName = getRetailerName();
    shoppingNextLink.textContent = nextItem
      ? t("shopping_next_link", nextItem.displayItem, retailerName)
      : t("shopping_done");
    if (nextItem) {
      shoppingNextLink.href = getRetailerSearchUrl(nextItem.item);
      shoppingNextLink.classList.remove("is-disabled");
      shoppingNextLink.removeAttribute("aria-disabled");
      shoppingNextLink.setAttribute("aria-label", t("shopping_next_link", nextItem.displayItem, retailerName));
    } else {
      shoppingNextLink.removeAttribute("href");
      shoppingNextLink.classList.add("is-disabled");
      shoppingNextLink.setAttribute("aria-disabled", "true");
    }
  }

  renderShoppingMobileBar({
    hasItems: items.length > 0,
    nextItem,
    checkedCount,
  });

  if (!visibleGroups.length) {
    shoppingList.innerHTML = `<p>${t("shopping_done")}</p>`;
    return;
  }

  visibleGroups.forEach((group) => {
    const section = document.createElement("section");
    section.className = "shop-category";

    const header = document.createElement("div");
    header.className = "shop-category-head";

    const headingWrap = document.createElement("div");
    const heading = document.createElement("h3");
    heading.className = "shop-heading";
    heading.textContent = translateShoppingCategory(group.category);
    const sub = document.createElement("p");
    sub.className = "shop-category-meta";
    sub.textContent = t("shopping_category_summary", group.remainingCount, group.totalCount);
    headingWrap.append(heading, sub);

    const countBadge = document.createElement("span");
    countBadge.className = "shop-category-count";
    countBadge.textContent = String(group.totalCount);

    header.append(headingWrap, countBadge);
    section.appendChild(header);

    const itemList = document.createElement("div");
    itemList.className = "shop-category-items";

    group.items.forEach((ingredient) => {
      const row = document.createElement("label");
      row.className = "shop-item";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.className = "shop-checkbox";
      checkbox.checked = ingredient.checked;

      const copy = document.createElement("span");
      copy.className = "shop-copy";

      const itemName = document.createElement("strong");
      itemName.className = "shop-item-name";
      if (group.category === "Pantry" && /chilli/i.test(ingredient.displayItem)) {
        itemName.innerHTML = ingredient.displayItem.replace(/chilli/gi, (match) => `<span class="chilli-trigger">${match}</span>`);
      } else {
        itemName.textContent = ingredient.displayItem;
      }

      const itemMeta = document.createElement("small");
      itemMeta.className = "shop-item-meta";
      itemMeta.textContent = ingredient.displayQty;
      copy.append(itemName, itemMeta);

      const retailerLink = document.createElement("a");
      const isColruyt = preferredRetailer === "colruyt";
      retailerLink.className = `shop-retailer-link ${isColruyt ? "colruyt-link" : "woolworths-link"}`;
      retailerLink.href = getRetailerSearchUrl(ingredient.item);
      retailerLink.target = "_blank";
      retailerLink.rel = "noopener noreferrer";
      retailerLink.setAttribute(
        "aria-label",
        isColruyt ? `Rechercher ${ingredient.displayItem} sur Colruyt` : `Search ${ingredient.displayItem} on Woolworths`
      );
      const logo = document.createElement("img");
      logo.src = isColruyt
        ? "https://www.element61.be/sites/default/files/styles/max_325x325/public/img_company_logos/Colruyt.png.webp?itok=5VR0mLrI"
        : "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTyZ8o4wGHBjezVaPKrg-ffgW-ph2TzVuMCEw&s";
      logo.alt = isColruyt ? "Colruyt" : "Woolworths";
      logo.loading = "lazy";
      const retailerText = document.createElement("span");
      retailerText.textContent = getRetailerName();
      retailerLink.append(logo, retailerText);
      retailerLink.addEventListener("click", (event) => {
        event.stopPropagation();
      });

      row.classList.toggle("is-checked", ingredient.checked);
      checkbox.addEventListener("change", (event) => {
        checkedItems[ingredient.key] = event.target.checked;
        saveState();
        renderShoppingList();
      });

      row.append(checkbox, copy, retailerLink);
      itemList.appendChild(row);
    });

    section.appendChild(itemList);
    shoppingList.appendChild(section);
  });

  const chilliTriggers = shoppingList.querySelectorAll(".chilli-trigger");
  chilliTriggers.forEach((trigger) => {
    trigger.addEventListener("click", (event) => {
      event.stopPropagation();
      if (!chilliModal) return;
      chilliModal.classList.add("is-open");
      chilliModal.setAttribute("aria-hidden", "false");
    });
  });
}

function formatQuantity(qty, unit) {
  const unitKey = (unit || "").toLowerCase();
  const countUnits = new Set([
    "pcs",
    "stalks",
    "bunch",
    "head",
    "pack",
    "can",
    "cans",
    "sheet",
  ]);

  if (countUnits.has(unitKey)) {
    return Math.ceil(qty);
  }

  if (unitKey === "g" || unitKey === "ml") {
    return Math.ceil(qty / 10) * 10;
  }

  if (unitKey === "cup" || unitKey === "cups") {
    return Math.ceil(qty * 4) / 4;
  }

  if (unitKey === "tbsp") {
    return Math.ceil(qty * 2) / 2;
  }

  if (unitKey === "tsp") {
    return Math.ceil(qty * 4) / 4;
  }

  const rounded = Math.round(qty * 100) / 100;
  return Number.isInteger(rounded) ? rounded : rounded.toFixed(2);
}

function groupShoppingItems(items) {
  const order = [
    "Produce",
    "Meat & Seafood",
    "Dairy",
    "Grains & Pasta",
    "Canned & Jarred",
    "Frozen",
    "Pantry",
  ];

  const pantryItems = new Set([
    "olive oil",
    "butter",
    "salt",
    "black pepper",
    "pepper",
    "nutmeg",
    "cumin",
    "paprika",
    "turmeric",
    "curry powder",
    "garam masala",
    "oregano",
    "thyme",
    "mixed herbs",
    "herbes de provence",
    "chilli powder",
    "chilli flakes",
    "bay leaf",
    "mustard",
    "dijon mustard",
    "brown sugar",
    "soy sauce",
    "honey",
    "sesame oil",
    "sesame seeds",
  ]);

  const categories = new Map();

  items.forEach((ingredient) => {
    const name = ingredient.item.toLowerCase();
    let category = "Pantry";

    if (pantryItems.has(name)) {
      category = "Pantry";
    } else if (name === "fresh tomato") {
      category = "Produce";
    } else if (name === "canned chopped tomatoes" || name === "canned polpa tomatoes" || name === "paste tomato") {
      category = "Canned & Jarred";
    } else if (/(chicken|beef|pork|lamb|fish|salmon|prawn|turkey)/.test(name)) {
      category = "Meat & Seafood";
    } else if (/(milk|cream|cheese|ricotta|parmesan|gruyere|mozzarella|goat cheese|butter)/.test(name)) {
      category = "Dairy";
    } else if (/(rice|pasta|lasagne|couscous|quinoa|flour|breadcrumbs)/.test(name)) {
      category = "Grains & Pasta";
    } else if (/(canned|can|beans|chickpeas|lentils|puree|paste|pulp|stock)/.test(name)) {
      category = "Canned & Jarred";
    } else if (/(frozen|peas)/.test(name)) {
      category = "Frozen";
    } else {
      category = "Produce";
    }

    if (!categories.has(category)) categories.set(category, []);
    categories.get(category).push(ingredient);
  });

  // Sort items within each category alphabetically
  categories.forEach((list, key) => {
    list.sort((a, b) => a.item.localeCompare(b.item));
    categories.set(key, list);
  });

  // Ensure pantry is last
  const ordered = [];
  order.forEach((cat) => {
    if (categories.has(cat)) ordered.push([cat, categories.get(cat)]);
  });
  return ordered;
}

function formatIngredientForDisplay(ingredient, scaledQty) {
  const unitKey = (ingredient.unit || "").toLowerCase();
  const itemKey = ingredient.item.toLowerCase();
  const cupToGram = {
    "parmesan": 100,
    "light cheese": 120,
    "mozzarella light": 120,
    "feta": 150,
    "ricotta": 250,
    "breadcrumbs": 60,
    "wholemeal breadcrumbs": 60,
    "quinoa": 170,
    "brown rice": 190,
    "jasmine rice": 190,
    "couscous": 180,
    "pearled barley": 200,
    "spaghetti": 100,
    "wholemeal pasta": 100,
  };

  if ((unitKey === "cup" || unitKey === "cups") && cupToGram[itemKey]) {
    const grams = scaledQty * cupToGram[itemKey];
    const displayQty = formatQuantity(grams, "g");
    const displayItem = translateIngredientItem(ingredient.item);
    return `${displayItem}: ${displayQty} g`;
  }

  const displayQty = formatQuantity(scaledQty, ingredient.unit);
  const displayItem = translateIngredientItem(ingredient.item);
  return `${displayItem}: ${displayQty} ${ingredient.unit}`;
}

function parseStepDurationMinutes(text) {
  const lower = String(text).toLowerCase();
  const hourMatch = lower.match(/(\d+)\s*(?:h|hour|hours)\b/);
  let minutes = 0;
  if (hourMatch) minutes += parseInt(hourMatch[1], 10) * 60;

  const minRange = lower.match(/(\d+)\s*(?:-|to)\s*(\d+)\s*(?:min|mins|minutes)\b/);
  if (minRange) {
    minutes += parseInt(minRange[2], 10);
  } else {
    const minMatch = lower.match(/(\d+)\s*(?:min|mins|minutes)\b/);
    if (minMatch) minutes += parseInt(minMatch[1], 10);
  }
  return minutes;
}

function formatTimer(minutes) {
  const totalSeconds = Math.max(0, minutes) * 60;
  const mm = Math.floor(totalSeconds / 60);
  const ss = totalSeconds % 60;
  return `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}

function playTimerSound() {
  try {
    const context = new (window.AudioContext || window.webkitAudioContext)();
    const osc = context.createOscillator();
    const gain = context.createGain();
    osc.type = "sine";
    osc.frequency.value = 880;
    gain.gain.value = 0.15;
    osc.connect(gain);
    gain.connect(context.destination);
    osc.start();
    setTimeout(() => {
      osc.stop();
      context.close();
    }, 700);
  } catch (error) {
    // ignore audio errors
  }
}

function renderCookOverview(planIds) {
  if (!cookOverview) return;
  cookOverview.innerHTML = "";

  const doneCount = planIds.filter((recipeId) => isCookRecipeDone(recipeId)).length;
  const summary = document.createElement("div");
  summary.className = "cook-summary";

  const copy = document.createElement("div");
  copy.className = "cook-summary-copy";
  const title = document.createElement("h3");
  title.textContent = t("cook_summary_title");
  const text = document.createElement("p");
  text.textContent = t("cook_summary_sub");
  const status = document.createElement("p");
  status.className = "cook-summary-status";
  status.textContent = t("cook_summary_status", planIds.length, doneCount);
  copy.append(title, text, status);

  const actions = document.createElement("div");
  actions.className = "cook-summary-actions";
  const startButton = document.createElement("button");
  startButton.type = "button";
  startButton.className = "primary";
  startButton.textContent = t("start_cooking");
  startButton.disabled = !planIds.length;
  startButton.addEventListener("click", () => {
    const nextRecipeId = ensureCookRecipeSelection();
    if (nextRecipeId) {
      openCookRecipe(nextRecipeId, { scroll: true });
    }
  });
  actions.appendChild(startButton);

  summary.append(copy, actions);
  cookOverview.appendChild(summary);
}

function renderCookRecipeList(planIds) {
  if (!cookRecipeList) return;
  cookRecipeList.innerHTML = "";

  const header = document.createElement("div");
  header.className = "cook-list-header";
  const title = document.createElement("h3");
  title.textContent = t("cook_list_title");
  const text = document.createElement("p");
  text.textContent = t("cook_list_sub");
  header.append(title, text);
  cookRecipeList.appendChild(header);

  if (!planIds.length) {
    const empty = document.createElement("div");
    empty.className = "empty-state";
    empty.innerHTML = `<p>${t("cook_list_empty")}</p>`;
    cookRecipeList.appendChild(empty);
    return;
  }

  const nextRecipeId = planIds.find((recipeId) => !isCookRecipeDone(recipeId)) || "";
  const list = document.createElement("div");
  list.className = "cook-list-stack";

  planIds.forEach((recipeId, index) => {
    const recipe = getRecipeById(recipeId);
    if (!recipe) return;
    const isActive = recipeId === currentCookRecipeId;
    const isDone = isCookRecipeDone(recipeId);
    const button = document.createElement("button");
    button.type = "button";
    button.className = "cook-recipe-button";
    if (isActive) button.classList.add("is-active");
    if (isDone) button.classList.add("is-done");
    button.addEventListener("click", () => {
      openCookRecipe(recipeId);
    });

    const thumb = document.createElement("span");
    thumb.className = "cook-recipe-thumb";
    const thumbImg = document.createElement("img");
    thumbImg.src = getRecipeImage(recipe) || buildRecipeFallbackImage(recipe);
    thumbImg.alt = "";
    thumbImg.loading = "eager";
    thumbImg.decoding = "async";
    thumbImg.draggable = false;
    thumbImg.addEventListener("error", () => {
      thumbImg.src = buildRecipeFallbackImage(recipe);
    }, { once: true });
    thumb.appendChild(thumbImg);

    const copy = document.createElement("div");
    copy.className = "cook-recipe-copy";
    const name = document.createElement("strong");
    name.textContent = getRecipeName(recipe);
    const meta = document.createElement("span");
    meta.textContent = `${t("cook_recipe_position", index + 1, planIds.length)} · ${recipe.time}`;
    copy.append(name, meta);

    const badge = document.createElement("span");
    badge.className = "cook-recipe-badge";
    if (isActive) {
      badge.textContent = t("cook_badge_active");
      badge.classList.add("is-active");
    } else if (isDone) {
      badge.textContent = t("cook_badge_done");
      badge.classList.add("is-done");
    } else if (recipeId === nextRecipeId) {
      badge.textContent = t("cook_badge_next");
    } else {
      badge.textContent = "";
      badge.classList.add("is-hidden");
    }

    const action = document.createElement("span");
    action.className = "cook-recipe-start";
    action.textContent = isActive ? t("cook_recipe_continue") : t("cook_recipe_start");

    button.append(thumb, copy, badge, action);
    list.appendChild(button);
  });

  cookRecipeList.appendChild(list);
}

function renderCookCard(recipeId) {
  const recipe = getRecipeById(recipeId);
  if (!recipe || !cookCard) {
    renderCookEmpty();
    return;
  }

  const planIds = getCookPlanIds();
  const recipeIndex = planIds.indexOf(recipeId);
  const isDone = isCookRecipeDone(recipeId);
  const servings =
    (selectedServingsByWeek[cookWeekKey] || {})[recipeId] ||
    selectedServings[recipeId] ||
    DEFAULT_SERVINGS;
  const stepsForRecipe = getRecipeSteps(recipe);
  const checks = getCookStepChecks(recipeId);
  const checkedStepCount = stepsForRecipe.filter((_, index) => Boolean(checks[String(index)])).length;
  const currentStepIndex = getCurrentCookStepIndex(recipeId, stepsForRecipe);
  const currentStep = stepsForRecipe[currentStepIndex] || "";
  const isCurrentStepChecked = Boolean(checks[String(currentStepIndex)]);
  const nextRecipeId = getNextCookRecipeId(recipeId);

  renderCookMobileBar({ recipeId, stepIndex: currentStepIndex, stepCount: stepsForRecipe.length });

  cookCard.innerHTML = "";

  const shell = document.createElement("div");
  shell.className = "cook-focus";
  if (isDone) shell.classList.add("is-done");

  const header = document.createElement("div");
  header.className = "cook-header";

  const heroImage = document.createElement("div");
  heroImage.className = "cook-hero-image";
  const heroImg = document.createElement("img");
  heroImg.src = getRecipeImage(recipe) || buildRecipeFallbackImage(recipe);
  heroImg.alt = getRecipeName(recipe);
  heroImg.loading = "eager";
  heroImg.decoding = "async";
  heroImg.draggable = false;
  heroImg.addEventListener("error", () => {
    heroImg.src = buildRecipeFallbackImage(recipe);
  }, { once: true });
  heroImage.appendChild(heroImg);

  const titleWrap = document.createElement("div");
  titleWrap.className = "cook-title-wrap";
  const position = document.createElement("span");
  position.className = "cook-position";
  position.textContent = t("cook_recipe_position", Math.max(recipeIndex + 1, 1), planIds.length);
  const heading = document.createElement("h3");
  heading.textContent = getRecipeName(recipe);
  const meta = document.createElement("p");
  meta.className = "cook-meta";
  meta.textContent = `${recipe.time} · ${servings} ${t("servings_label")} · ${t("cook_section_steps_count", checkedStepCount, stepsForRecipe.length)}`;
  const status = document.createElement("span");
  status.className = "cook-status-pill";
  status.textContent = isDone ? t("cook_status_complete") : t("cook_status_in_progress");
  if (isDone) status.classList.add("is-done");
  titleWrap.append(position, heading, meta, status);

  const actions = document.createElement("div");
  actions.className = "cook-header-actions";
  const servingControls = document.createElement("div");
  servingControls.className = "serving-controls cook-serving-controls";
  const servingLabel = document.createElement("span");
  servingLabel.textContent = t("servings_label");
  const minus = document.createElement("button");
  minus.type = "button";
  minus.className = "ghost";
  minus.textContent = "-";
  minus.addEventListener("click", () => {
    const nextServings = Math.max(1, servings - 1);
    if (!selectedServingsByWeek[cookWeekKey]) selectedServingsByWeek[cookWeekKey] = {};
    selectedServingsByWeek[cookWeekKey][recipeId] = nextServings;
    selectedServings[recipeId] = nextServings;
    saveState();
    renderSelectedInLibrary();
    renderShoppingList();
    renderCookCard(recipeId);
  });
  const servingCount = document.createElement("span");
  servingCount.className = "count";
  servingCount.textContent = String(servings);
  const plus = document.createElement("button");
  plus.type = "button";
  plus.className = "ghost";
  plus.textContent = "+";
  plus.addEventListener("click", () => {
    const nextServings = servings + 1;
    if (!selectedServingsByWeek[cookWeekKey]) selectedServingsByWeek[cookWeekKey] = {};
    selectedServingsByWeek[cookWeekKey][recipeId] = nextServings;
    selectedServings[recipeId] = nextServings;
    saveState();
    renderSelectedInLibrary();
    renderShoppingList();
    renderCookCard(recipeId);
  });
  servingControls.append(servingLabel, minus, servingCount, plus);
  actions.append(servingControls);
  header.append(heroImage, titleWrap, actions);

  const tip = document.createElement("p");
  tip.className = "cook-focus-tip";
  tip.textContent = t("cook_focus_tip");

  const body = document.createElement("div");
  body.className = "cook-body";

  const ingredientsSection = document.createElement("details");
  ingredientsSection.className = "cook-panel-block cook-ingredients-panel";
  const ingredientsSummary = document.createElement("summary");
  ingredientsSummary.className = "cook-section-head";
  const ingredientsTitle = document.createElement("h4");
  ingredientsTitle.textContent = t("cook_section_ingredients");
  const ingredientsCount = document.createElement("span");
  ingredientsCount.textContent = t("cook_section_ingredients_count", recipe.ingredients.length);
  ingredientsSummary.append(ingredientsTitle, ingredientsCount);
  const ingredientsList = document.createElement("div");
  ingredientsList.className = "cook-ingredients";
  if (recipe.ingredients.length) {
    recipe.ingredients.forEach((ingredient) => {
      const item = document.createElement("div");
      item.className = "cook-ingredient-item";
      const scaled = (ingredient.qty / recipe.servings) * servings;
      item.textContent = formatIngredientForDisplay(ingredient, scaled);
      ingredientsList.appendChild(item);
    });
  } else {
    const empty = document.createElement("div");
    empty.className = "cook-ingredient-item is-empty";
    empty.textContent = t("ingredients_empty");
    ingredientsList.appendChild(empty);
  }
  ingredientsSection.append(ingredientsSummary, ingredientsList);

  const stepsSection = document.createElement("section");
  stepsSection.className = "cook-panel-block cook-steps-panel";
  if (stepsForRecipe.length) {
    const progress = document.createElement("div");
    progress.className = "cook-step-progress";
    const progressText = document.createElement("span");
    progressText.textContent = t("cook_step_progress", currentStepIndex + 1, stepsForRecipe.length);
    const progressBar = document.createElement("div");
    progressBar.className = "cook-progress-bar";
    const progressFill = document.createElement("span");
    progressFill.style.width = `${Math.round(((currentStepIndex + 1) / stepsForRecipe.length) * 100)}%`;
    progressBar.appendChild(progressFill);
    progress.append(progressText, progressBar);

    const stepCard = document.createElement("article");
    stepCard.className = "cook-step-card";
    if (isCurrentStepChecked) stepCard.classList.add("is-checked");

    const stepNumber = document.createElement("span");
    stepNumber.className = "cook-step-number";
    stepNumber.textContent = String(currentStepIndex + 1);

    const stepText = document.createElement("p");
    stepText.className = "step-text";
    stepText.textContent = formatStepWithQuantities(currentStep, recipe, servings);

    const stepDoneButton = document.createElement("button");
    stepDoneButton.type = "button";
    stepDoneButton.className = isCurrentStepChecked ? "primary cook-step-done-button" : "ghost cook-step-done-button";
    stepDoneButton.textContent = isCurrentStepChecked ? t("cook_step_complete") : t("cook_mark_step_done");
    stepDoneButton.addEventListener("click", () => {
      setCookStepChecked(recipeId, currentStepIndex, !isCurrentStepChecked);
      renderCookOverview(planIds);
      renderCookRecipeList(planIds);
      renderCookCard(recipeId);
    });

    stepCard.append(stepNumber, stepText, stepDoneButton);

    const stepNav = document.createElement("div");
    stepNav.className = "cook-step-nav";

    const previousButton = document.createElement("button");
    previousButton.type = "button";
    previousButton.className = "ghost";
    previousButton.textContent = t("cook_previous_step");
    previousButton.disabled = currentStepIndex <= 0;
    previousButton.addEventListener("click", () => {
      setCurrentCookStepIndex(recipeId, currentStepIndex - 1, stepsForRecipe);
      renderCookCard(recipeId);
    });

    const nextButton = document.createElement("button");
    nextButton.type = "button";
    nextButton.className = "primary";
    nextButton.textContent = currentStepIndex >= stepsForRecipe.length - 1 ? t("cook_finish_recipe") : t("cook_next_step");
    nextButton.addEventListener("click", () => {
      if (currentStepIndex < stepsForRecipe.length - 1) {
        setCurrentCookStepIndex(recipeId, currentStepIndex + 1, stepsForRecipe);
        renderCookCard(recipeId);
        return;
      }
      setCookRecipeDone(recipeId, true);
      if (nextRecipeId && nextRecipeId !== recipeId) {
        openCookRecipe(nextRecipeId, { scroll: true });
      } else {
        renderCookMode();
      }
      renderWeeklyFlow();
    });

    stepNav.append(previousButton, nextButton);
    stepsSection.append(progress, stepCard, stepNav);
  } else {
    const empty = document.createElement("div");
    empty.className = "step";
    empty.textContent = t("cook_steps_empty");
    stepsSection.appendChild(empty);
  }

  body.append(stepsSection, ingredientsSection);

  const noteSection = document.createElement("div");
  noteSection.className = "note-section cook-note-section";
  const noteLabel = document.createElement("label");
  noteLabel.className = "note-label";
  noteLabel.textContent = t("recipe_note");
  const noteInput = document.createElement("textarea");
  noteInput.className = "note-input";
  noteInput.rows = 3;
  noteInput.placeholder = t("recipe_note_placeholder");
  noteInput.value = recipeNotesById[recipe.id] || "";
  const persistNote = () => {
    const value = noteInput.value.trim();
    if (value) {
      recipeNotesById[recipe.id] = value;
    } else {
      delete recipeNotesById[recipe.id];
    }
    saveState();
  };
  noteInput.addEventListener("blur", persistNote);
  const noteActions = document.createElement("div");
  noteActions.className = "note-actions";
  const saveBtn = document.createElement("button");
  saveBtn.type = "button";
  saveBtn.className = "ghost";
  saveBtn.textContent = t("note_save");
  saveBtn.addEventListener("click", persistNote);
  const clearBtn = document.createElement("button");
  clearBtn.type = "button";
  clearBtn.className = "ghost";
  clearBtn.textContent = t("note_clear");
  clearBtn.addEventListener("click", () => {
    noteInput.value = "";
    delete recipeNotesById[recipe.id];
    saveState();
  });
  noteActions.append(saveBtn, clearBtn);
  noteSection.append(noteLabel, noteInput, noteActions);

  const footer = document.createElement("div");
  footer.className = "cook-footer";
  if (recipe.source_url) {
    const link = document.createElement("a");
    link.className = "ghost link-btn";
    link.href = recipe.source_url;
    link.target = "_blank";
    link.rel = "noopener";
    link.textContent = t("cook_open_link");
    footer.appendChild(link);
  }
  const doneButton = document.createElement("button");
  doneButton.type = "button";
  doneButton.className = isDone ? "ghost cook-done-button" : "primary cook-done-button";
  doneButton.textContent = isDone ? t("cook_mark_undone") : t("cook_mark_done");
  doneButton.addEventListener("click", () => {
    setCookRecipeDone(recipeId, !isDone);
    renderCookOverview(planIds);
    renderCookRecipeList(planIds);
    renderCookCard(recipeId);
    renderWeeklyFlow();
  });
  const nextRecipeButton = document.createElement("button");
  nextRecipeButton.type = "button";
  nextRecipeButton.className = "ghost";
  nextRecipeButton.textContent = nextRecipeId ? t("cook_next_recipe") : t("cook_no_next_recipe");
  nextRecipeButton.disabled = !nextRecipeId;
  nextRecipeButton.addEventListener("click", () => {
    if (nextRecipeId) openCookRecipe(nextRecipeId, { scroll: true });
  });
  footer.append(doneButton, nextRecipeButton);

  shell.append(header, tip, body, noteSection, footer);
  cookCard.appendChild(shell);
}

function renderCookEmpty() {
  if (!cookCard) return;
  if (cookMobileBar) {
    cookMobileBar.innerHTML = "";
    cookMobileBar.hidden = true;
  }
  cookCard.innerHTML = `
    <div class="empty-state">
      <h3>${t("cook_empty_plan_title")}</h3>
      <p>${t("cook_empty_plan_sub")}</p>
    </div>
  `;
}

function renderCookMode() {
  const planIds = getCookPlanIds();
  renderCookOverview(planIds);
  renderCookRecipeList(planIds);
  if (!planIds.length) {
    currentCookRecipeId = "";
    renderCookEmpty();
    return;
  }
  const nextRecipeId = ensureCookRecipeSelection();
  if (!nextRecipeId) {
    renderCookEmpty();
    return;
  }
  renderCookCard(nextRecipeId);
}

function renderMiniGrid() {
  if (!miniGrid) return;
  miniGrid.innerHTML = "";
  const weekLabelText = currentWeekKey ? formatWeekLabel(currentWeekKey) : t("summary_week");
  const recipeCount = selectedRecipes.length;
  const missingCount = aggregateShoppingList().filter(
    (ingredient) => !checkedItems[`${ingredient.item}|${ingredient.unit}`]
  ).length;

  const summaries = [
    { label: t("summary_week"), value: weekLabelText },
    { label: t("summary_recipes"), value: String(recipeCount) },
    { label: t("summary_missing"), value: String(missingCount) },
  ];

  summaries.forEach((summary) => {
    const card = document.createElement("div");
    card.className = "mini-slot";
    const label = document.createElement("div");
    label.className = "mini-label";
    label.textContent = summary.label;
    const value = document.createElement("div");
    value.className = "mini-value";
    value.textContent = summary.value;
    card.append(label, value);
    miniGrid.appendChild(card);
  });
}

function formatWeekLabel(weekKey) {
  if (!weekKey) return "";
  const [yearPart, weekPart] = weekKey.split("-W");
  const year = parseInt(yearPart, 10);
  const week = parseInt(weekPart, 10);
  if (!year || !week) return "";
  const date = getDateFromISOWeek(year, week);
  const locale = getDateLocale();
  const label = date.toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "short", year: "numeric" });
  return `${t("week_starting")} ${label}`;
}

function getDateFromISOWeek(year, week) {
  const simple = new Date(Date.UTC(year, 0, 1 + (week - 1) * 7));
  const dow = simple.getUTCDay();
  const ISOweekStart = new Date(simple);
  if (dow <= 4) {
    ISOweekStart.setUTCDate(simple.getUTCDate() - simple.getUTCDay() + 1);
  } else {
    ISOweekStart.setUTCDate(simple.getUTCDate() + 8 - simple.getUTCDay());
  }
  return new Date(ISOweekStart.getUTCFullYear(), ISOweekStart.getUTCMonth(), ISOweekStart.getUTCDate());
}

function getWeekKeyFromDate(date) {
  const tmp = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = tmp.getUTCDay() || 7;
  tmp.setUTCDate(tmp.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1));
  const weekNum = Math.ceil(((tmp - yearStart) / 86400000 + 1) / 7);
  return `${tmp.getUTCFullYear()}-W${String(weekNum).padStart(2, "0")}`;
}

function getWeekStartFromDate(date) {
  const start = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const day = start.getDay() || 7;
  start.setDate(start.getDate() - (day - 1));
  start.setHours(0, 0, 0, 0);
  return start;
}

function getCurrentWeekKey() {
  const today = new Date();
  const tmp = new Date(Date.UTC(today.getFullYear(), today.getMonth(), today.getDate()));
  const dayNum = tmp.getUTCDay() || 7;
  tmp.setUTCDate(tmp.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1));
  const weekNum = Math.ceil(((tmp - yearStart) / 86400000 + 1) / 7);
  return `${tmp.getUTCFullYear()}-W${String(weekNum).padStart(2, "0")}`;
}

function getNextWeekKey() {
  const today = new Date();
  const start = getWeekStartFromDate(today);
  const day = today.getDay(); // 0=Sun, 1=Mon
  if (day >= 2) {
    start.setDate(start.getDate() + 7);
  }
  return getWeekKeyFromDate(start);
}

function setupWeekPicker({ input, trigger, popover, labelNode, onChange }) {
  if (!input || !trigger || !popover) return;
  let currentMonth = new Date();

  const updateTrigger = () => {
    const weekKey = input.value;
    if (labelNode) {
      labelNode.textContent = weekKey ? formatWeekLabel(weekKey) : "";
    }
    trigger.textContent = weekKey ? formatWeekLabel(weekKey) : t("week_select");
  };

  const render = () => {
    popover.innerHTML = "";
    const locale = getDateLocale();
    const monthLabel = currentMonth.toLocaleDateString(locale, { month: "long", year: "numeric" });

    const header = document.createElement("div");
    header.className = "week-header";
    const prev = document.createElement("button");
    prev.type = "button";
    prev.textContent = "←";
    prev.addEventListener("click", () => {
      currentMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1);
      render();
    });
    const title = document.createElement("div");
    title.className = "week-month";
    title.textContent = monthLabel;
    const next = document.createElement("button");
    next.type = "button";
    next.textContent = "→";
    next.addEventListener("click", () => {
      currentMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1);
      render();
    });
    header.append(prev, title, next);

    const grid = document.createElement("div");
    grid.className = "week-grid";
    const dayNames = isFrenchLanguage()
      ? ["L", "M", "M", "J", "V", "S", "D"]
      : ["M", "T", "W", "T", "F", "S", "S"];
    dayNames.forEach((label) => {
      const day = document.createElement("div");
      day.className = "week-day week-day-label";
      day.textContent = label;
      grid.appendChild(day);
    });

    const monthStart = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1);
    const gridStart = getWeekStartFromDate(monthStart);
    const selectedWeekKey = input.value;
    const selectedStart = selectedWeekKey
      ? getDateFromISOWeek(parseInt(selectedWeekKey.split("-W")[0], 10), parseInt(selectedWeekKey.split("-W")[1], 10))
      : null;

    for (let i = 0; i < 42; i += 1) {
      const date = new Date(gridStart.getFullYear(), gridStart.getMonth(), gridStart.getDate() + i);
      const cell = document.createElement("div");
      cell.className = "week-day";
      cell.textContent = String(date.getDate());
      if (date.getMonth() !== currentMonth.getMonth()) cell.classList.add("is-out");

      if (selectedStart) {
        const diff = (date - selectedStart) / 86400000;
        if (diff >= 0 && diff <= 6) cell.classList.add("is-in-week");
        if (diff === 0) cell.classList.add("is-selected");
      }

      cell.addEventListener("click", () => {
        const weekKey = getWeekKeyFromDate(date);
        input.value = weekKey;
        onChange();
        updateTrigger();
        popover.classList.remove("open");
      });
      grid.appendChild(cell);
    }

    const actions = document.createElement("div");
    actions.className = "week-actions";
    const clearBtn = document.createElement("button");
    clearBtn.type = "button";
    clearBtn.textContent = t("week_clear");
    clearBtn.addEventListener("click", () => {
      input.value = "";
      onChange();
      updateTrigger();
      popover.classList.remove("open");
    });
    const thisWeek = document.createElement("button");
    thisWeek.type = "button";
    thisWeek.textContent = t("week_this");
    thisWeek.addEventListener("click", () => {
      input.value = getCurrentWeekKey();
      onChange();
      updateTrigger();
      popover.classList.remove("open");
    });
    actions.append(clearBtn, thisWeek);

    popover.append(header, grid, actions);
  };

  trigger.addEventListener("click", () => {
    popover.classList.toggle("open");
    render();
  });

  document.addEventListener("click", (event) => {
    if (!popover.contains(event.target) && !trigger.contains(event.target)) {
      popover.classList.remove("open");
    }
  });

  updateTrigger();
}

function setWeekFromTopPicker({ restoreStage = false } = {}) {
  const desiredStage = normalizeStage(currentStage);
  currentWeekKey = (topWeekPicker && topWeekPicker.value) || getNextWeekKey();
  cookWeekKey = currentWeekKey;
  selectedRecipes = [...(selectedRecipesByWeek[currentWeekKey] || [])];
  checkedItems = { ...(checkedItemsByWeek[currentWeekKey] || {}) };
  selectedServings = { ...(selectedServingsByWeek[currentWeekKey] || {}) };
  if (weekLabel) weekLabel.textContent = formatWeekLabel(currentWeekKey);
  if (cookWeekLabel) cookWeekLabel.textContent = formatWeekLabel(cookWeekKey);
  if (topWeekLabel) topWeekLabel.textContent = formatWeekLabel(currentWeekKey);
  const cookIds = selectedRecipesByWeek[cookWeekKey] || [];
  if (!currentCookRecipeId || !cookIds.includes(currentCookRecipeId)) {
    currentCookRecipeId = "";
  }
  if (restoreStage) {
    const restoredStage = desiredStage !== "plan" && selectedRecipes.length === 0 ? "plan" : desiredStage;
    setView(restoredStage);
    if (restoredStage === "cook") ensureCookRecipeSelection();
  } else {
    syncCurrentStage();
  }
  persistUiState();
  refreshAll();
}

function populateTopWeekOptions() {
  if (!topWeekPicker) return;
  topWeekPicker.innerHTML = "";
  const nowKey = getNextWeekKey();
  const [yearPart, weekPart] = nowKey.split("-W");
  const baseYear = parseInt(yearPart, 10);
  const baseWeek = parseInt(weekPart, 10);
  const totalWeeks = 20;

  for (let i = -2; i < totalWeeks; i += 1) {
    const date = getDateFromISOWeek(baseYear, baseWeek);
    date.setDate(date.getDate() + i * 7);
    const weekKey = getWeekKeyFromDate(date);
    const option = document.createElement("option");
    option.value = weekKey;
    option.textContent = formatWeekLabel(weekKey);
    topWeekPicker.appendChild(option);
  }
}

function refreshAll() {
  applyTranslations();
  syncCurrentStage();
  if (topWeekLabel) {
    topWeekLabel.textContent = currentWeekKey ? formatWeekLabel(currentWeekKey) : "";
  }
  if (currentWeekKey && weekLabel) {
    weekLabel.textContent = formatWeekLabel(currentWeekKey);
  }
  if (cookWeekKey) {
    if (cookWeekLabel) cookWeekLabel.textContent = formatWeekLabel(cookWeekKey);
  }
  renderSelectedInLibrary();
  renderShoppingList();
  renderCookMode();
  renderMiniGrid();
  renderRecipeGrid();
  renderPlanningShortcuts();
  renderPantryPickerSection();
  renderFrequencyTable();
  renderRecentWeeks();
  if (heroCount) {
    heroCount.textContent = t("planned_count", selectedRecipes.length, WEEKLY_RECIPE_TARGET);
  }
  renderWeeklyFlow();
  if (shouldRestoreRecipeDetails && recipeDetailsOpen && currentStage === "plan") {
    shouldRestoreRecipeDetails = false;
    const recipe = getRecipeById(lastOpenedRecipeId);
    if (recipe) {
      renderRecipeDetails(recipe);
    } else {
      recipeDetailsOpen = false;
      persistUiState();
    }
  }
  refreshSyncStatus();
}

populateTopWeekOptions();
if (topWeekPicker) {
  const storedWeekKey = sanitizeStoredWeekKey(storedUiState.selectedWeekKey);
  topWeekPicker.value = storedWeekKey || getNextWeekKey();
}
lastOpenedRecipeId = getRecipeById(storedUiState.lastOpenedRecipeId) ? storedUiState.lastOpenedRecipeId : "";
currentStage = normalizeStage(storedUiState.activeMode);
shouldRestoreRecipeDetails = Boolean(recipeDetailsOpen && lastOpenedRecipeId && currentStage === "plan");
setWeekFromTopPicker({ restoreStage: true });
refreshSyncStatus();
restartSyncPolling();
if (isSyncEnabled()) {
  void pullPlannerStateFromRemote();
}

if (recipeSearch) {
  recipeSearch.addEventListener("input", () => renderRecipeGrid());
}
if (pantryIngredientSearch) {
  pantryIngredientSearch.addEventListener("input", () => renderPantrySearchResults());
}
if (pantryClear) {
  pantryClear.addEventListener("click", () => {
    pantryInventory = {};
    savePantryInventory();
    renderPantryPickerSection();
  });
}
if (filterUtensil) {
  filterUtensil.addEventListener("change", () => renderRecipeGrid());
}
if (filterProtein) {
  filterProtein.addEventListener("change", () => renderRecipeGrid());
}
if (filterMeal) {
  filterMeal.addEventListener("change", () => renderRecipeGrid());
}

const clearChecks = document.getElementById("clear-checks");
if (duplicateLastWeekButton) {
  duplicateLastWeekButton.addEventListener("click", () => {
    duplicateLastWeekPlan();
  });
}

if (autoFillWeekButton) {
  autoFillWeekButton.addEventListener("click", () => {
    autoFillWeekPlan();
  });
}

if (shoppingToggleChecked) {
  shoppingToggleChecked.addEventListener("click", () => {
    toggleHideCheckedShoppingItems();
  });
}

if (clearChecks) {
  clearChecks.addEventListener("click", () => {
    checkedItems = {};
    saveState();
    renderShoppingList();
  });
}

const clearPlan = document.getElementById("clear-plan");
if (clearWeekButton) {
  clearWeekButton.addEventListener("click", () => {
    clearCurrentWeekPlan();
  });
}

if (clearPlan) {
  clearPlan.addEventListener("click", () => {
    clearCurrentWeekPlan();
  });
}

if (topWeekPicker) {
  topWeekPicker.addEventListener("change", () => {
    setWeekFromTopPicker();
  });
}

window.addEventListener("focus", () => {
  if (!isSyncEnabled()) return;
  void pullPlannerStateFromRemote();
});

if (languageSelect) {
  languageSelect.addEventListener("change", (event) => {
    currentLanguage = normalizeLanguageCode(event.target.value);
    persistLocalState();
    scheduleRemoteSync();
    const selectedWeekKey = topWeekPicker ? topWeekPicker.value : "";
    populateTopWeekOptions();
    if (topWeekPicker && selectedWeekKey) {
      topWeekPicker.value = selectedWeekKey;
    }
    refreshAll();
  });
}

if (openFrequency && frequencyModal) {
  openFrequency.addEventListener("click", () => {
    renderFrequencyTable();
    frequencyModal.classList.add("is-open");
    frequencyModal.setAttribute("aria-hidden", "false");
    requestAnimationFrame(() => {
      focusFrequencyRecentWindow();
    });
  });
}

if (closeFrequency && frequencyModal) {
  closeFrequency.addEventListener("click", () => {
    frequencyModal.classList.remove("is-open");
    frequencyModal.setAttribute("aria-hidden", "true");
  });
}

if (recipeModal) {
  recipeModal.addEventListener("click", (event) => {
    const shouldClose = event.target?.dataset?.modalClose === "true";
    if (!shouldClose) return;
    recipeModal.classList.remove("is-open");
    recipeModal.setAttribute("aria-hidden", "true");
    recipeDetailsOpen = false;
    persistUiState();
  });
}

if (chilliModal) {
  chilliModal.addEventListener("click", (event) => {
    const shouldClose = event.target?.dataset?.modalClose === "true";
    if (!shouldClose) return;
    chilliModal.classList.remove("is-open");
    chilliModal.setAttribute("aria-hidden", "true");
  });
}

if (frequencyModal) {
  frequencyModal.addEventListener("click", (event) => {
    const shouldClose = event.target?.dataset?.modalClose === "true";
    if (!shouldClose) return;
    frequencyModal.classList.remove("is-open");
    frequencyModal.setAttribute("aria-hidden", "true");
  });
}
